def calculate(exp):
    the_stack = []
    for ch in exp.split():
        if ch.isdigit():
            the_stack.append(int(ch))
        else:
            b = the_stack.pop()
            a = the_stack.pop()
            if ch == '+':
                the_stack.append(a + b)
            elif ch == '-':
                the_stack.append(a - b)
            elif ch == '*':
                the_stack.append(a * b)
            elif ch == '/':
                the_stack.append(a // b)
    return the_stack.pop()

